  // 2026-09-03 单向联动逻辑：需求对照面板不再向左侧页面渲染编号小点，也不再提供“小点点击后滚动右侧文档”的反向跳转；右侧 PRD 导航打开左侧对应页面的行为继续保留。

  // 2026-09-06 Markdown 缩进逻辑：条目可用 { text, indent } 保留原文二级列表空格；字符串仍按一级列表渲染，避免改变既有 PRD 数据与导航结构。
  function appendRequirementItem(list, entry) {
    var text = typeof entry === "string" ? entry : entry.text;
    var item = document.createElement("li");
    if (typeof entry === "object" && entry.indent) {
      item.className = "requirements-list-item-indent-" + entry.indent;
    }
    var separator = text.indexOf("：");
    if (separator > 0) {
      var strong = document.createElement("strong");
      strong.textContent = text.slice(0, separator + 1);
      item.appendChild(strong);
      item.appendChild(document.createTextNode(text.slice(separator + 1)));
    } else {
      item.textContent = text;
    }
    list.appendChild(item);
  }

  // 2026-09-06 表格导入逻辑：把需求详情中的 Markdown 二维表渲染为原生表格，仅保留文字与换行，不加载文档图片或附件。
  function appendRequirementTable(section, rows) {
    var viewport = document.createElement("div");
    viewport.className = "requirements-table-viewport";
    var table = document.createElement("table");
    table.className = "requirements-markdown-table";
    rows.forEach(function (row, rowIndex) {
      var tableRow = document.createElement("tr");
      row.forEach(function (cellText) {
        var cell = document.createElement(rowIndex === 0 ? "th" : "td");
        cell.textContent = cellText;
        tableRow.appendChild(cell);
      });
      (rowIndex === 0 ? (table.tHead || table.createTHead()) : (table.tBodies[0] || table.createTBody())).appendChild(tableRow);
    });
    viewport.appendChild(table);
    section.appendChild(viewport);
  }

