  header.innerHTML = '<div class="requirements-panel-heading-row"><h1 class="requirements-panel-title">需求对照</h1><div class="requirements-version-picker"><button type="button" class="requirements-version-select" aria-label="PRD 版本" aria-haspopup="menu" aria-expanded="false" aria-controls="requirementsVersionMenu" value="1.5"><span class="requirements-version-label">v1.5</span><span class="requirements-version-chevron" aria-hidden="true"></span></button><div class="requirements-version-menu" id="requirementsVersionMenu" role="menu" aria-label="PRD 版本" hidden><button type="button" role="menuitemradio" aria-checked="true" data-version="1.5">v1.5</button><button type="button" role="menuitemradio" aria-checked="false" data-version="1.4">v1.4</button></div></div><span class="requirements-panel-nav-hint">点击分类查看需求</span></div>';
